<?php
require_once __DIR__.'/../includes/functions.php';require_role('admin');verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){
 try{db()->prepare('INSERT INTO enrollments(student_id,class_id,academic_session) VALUES(?,?,?)')->execute([(int)$_POST['student_id'],(int)$_POST['class_id'],trim($_POST['academic_session'])]);audit('Enrolled student in class',null,'student_id='.$_POST['student_id'].' class_id='.$_POST['class_id']);flash('success','Student enrolled successfully.');}
 catch(Throwable $e){flash('danger','Could not enroll student. This student may already be enrolled in this class and session.');}redirect('enrollments.php');
}
$students=db()->query("SELECT s.student_id,s.roll_number,u.name FROM students s JOIN users u ON u.user_id=s.user_id WHERE u.status='active' ORDER BY u.name")->fetchAll();$classes=db()->query('SELECT * FROM classes ORDER BY department,semester')->fetchAll();$rows=db()->query('SELECT en.*,s.roll_number,u.name,c.class_name,c.department FROM enrollments en JOIN students s ON s.student_id=en.student_id JOIN users u ON u.user_id=s.user_id JOIN classes c ON c.class_id=en.class_id ORDER BY en.enrollment_id DESC')->fetchAll();include __DIR__.'/../includes/header.php';?>
<div class="row g-3"><div class="col-md-4"><div class="card"><div class="card-header">Enroll student</div><div class="card-body"><form method="post"><?=csrf_field()?><div class="mb-2"><label class="form-label">Student</label><select class="form-select" name="student_id" required><?php foreach($students as $s):?><option value="<?=$s['student_id']?>"><?=e($s['roll_number'].' · '.$s['name'])?></option><?php endforeach;?></select></div><div class="mb-2"><label class="form-label">Class</label><select class="form-select" name="class_id" required><?php foreach($classes as $c):?><option value="<?=$c['class_id']?>"><?=e($c['class_name'].' · '.$c['department'].' · Sem '.$c['semester'])?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label">Academic session</label><input class="form-control" name="academic_session" placeholder="2026-2027" required></div><button class="btn btn-primary">Enroll student</button></form></div></div></div><div class="col-md-8"><div class="card"><div class="card-header">Enrollment records</div><div class="table-responsive"><table class="table mb-0"><thead><tr><th>Roll number</th><th>Student</th><th>Class</th><th>Session</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['roll_number'])?></td><td><?=e($r['name'])?></td><td><?=e($r['class_name'].' · '.$r['department'])?></td><td><?=e($r['academic_session'])?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php include __DIR__.'/../includes/footer.php';?>
